#include <string>
#include <unordered_map>
#include <unordered_set>
using namespace std;

class Solution {
public:
    int minDeletions(string s) {
        unordered_map<char, int> freq;
        for (char c : s) freq[c]++;

        unordered_set<int> seen;
        int deletions = 0;

        for (auto& entry : freq) {
            while (entry.second > 0 && seen.count(entry.second)) {
                entry.second--;
                deletions++;
            }
            seen.insert(entry.second);
        }

        return deletions;
    }
};
